27	    /**
28	     * 追加一条待接收交接记录。
29	     */
30	    public void insert(String evidenceKey, String fromCustodian, String toCustodian,
31	                       LocalDateTime now) {
32	        jdbc.update("""
33	                        INSERT INTO transfer_record
34	                            (evidence_key, from_custodian, to_custodian, status, initiated_by, created_at, decided_at)
35	                        VALUES (?, ?, ?, ?, ?, ?, NULL)
36	                        """,
37	                evidenceKey, fromCustodian, toCustodian,
38	                TransferStatus.PENDING.name(), fromCustodian, now);
39	    }
