45	        List<TransferRecord> rows = jdbc.query(
46	                "SELECT * FROM transfer_record WHERE evidence_key = ? AND status = ?",
47	                ROW_MAPPER, evidenceKey, TransferStatus.PENDING.name());
48	        return rows.stream().findFirst();
49	    }
