51	    /**
52	     * 将待接收交接决定为 ACCEPTED 或 CANCELLED；仅当仍为 PENDING 时生效。
53	     *
54	     * @return 是否成功决定（false 表示已被并发事务先行决定）
55	     */
56	    public boolean decide(long id, TransferStatus decided, LocalDateTime decidedAt) {
57	        int updated = jdbc.update(
58	                "UPDATE transfer_record SET status = ?, decided_at = ? WHERE id = ? AND status = ?",
59	                decided.name(), decidedAt, id, TransferStatus.PENDING.name());
60	        return updated == 1;
