        return rows.stream().findFirst();
    }

    /**
     * 查询根箱整树全部箱（含根箱自身），按主键排序。
     */
    public List<Container> findByRootKey(String rootKey) {
        return jdbc.query(
                "SELECT * FROM evidence_container WHERE root_key = ? ORDER BY id",
                ROW_MAPPER, rootKey);
    }

    /**
     * 更新直接父箱（装箱挂接 / 拆箱置 NULL）。
     */
    public void updateParent(String containerKey, String parentKey, LocalDateTime now) {
        jdbc.update(
                "UPDATE evidence_container SET parent_key = ?, updated_at = ? WHERE container_key = ?",
                parentKey, now, containerKey);
    }

    /**
     * 批量更新一组箱的所属根箱（子树挂接或拆出时同步冗余列）。
     */
    public void updateRootKey(List<String> containerKeys, String rootKey, LocalDateTime now) {
        for (String key : containerKeys) {
            jdbc.update(
                    "UPDATE evidence_container SET root_key = ?, updated_at = ? WHERE container_key = ?",
                    rootKey, now, key);
        }
    }

    /**
     * 根箱成员版本条件递增：仅当当前版本等于 expectedVersion 时加一。
     *
     * @return 是否成功递增（false 表示版本不匹配，返回 409）
     */
    public boolean incrementVersion(String rootKey, int expectedVersion, LocalDateTime now) {
        int updated = jdbc.update(
                "UPDATE evidence_container SET version = version + 1, updated_at = ?"
                        + " WHERE container_key = ? AND version = ?",
                now, rootKey, expectedVersion);
        return updated == 1;
    }

    /**
     * 将根箱整树（仍为 SEALED 的箱）置为 TRANSFER_PENDING（交接发起冻结）。
     */
    public void freezeTree(String rootKey, LocalDateTime now) {
        jdbc.update(
                "UPDATE evidence_container SET status = ?, updated_at = ?"
                        + " WHERE root_key = ? AND status = ?",
                ContainerStatus.TRANSFER_PENDING.name(), now, rootKey,
                ContainerStatus.SEALED.name());
    }

    /**
     * 将根箱整树（仍为 TRANSFER_PENDING 的箱）置回 SEALED（交接取消；
     * 待接收期间被封条核验打坏的箱保持 SEAL_BROKEN 不变）。
     */
    public void unfreezeTree(String rootKey, LocalDateTime now) {
        jdbc.update(
                "UPDATE evidence_container SET status = ?, updated_at = ?"
                        + " WHERE root_key = ? AND status = ?",
                ContainerStatus.SEALED.name(), now, rootKey,
                ContainerStatus.TRANSFER_PENDING.name());
    }

    /**
     * 交接接受：整树保管人原子切换为接收人并回到 SEALED（仅仍冻结的箱）。
     */
    public void acceptTree(String rootKey, String toCustodian, LocalDateTime now) {
        jdbc.update(
                "UPDATE evidence_container SET custodian_id = ?, status = ?, updated_at = ?"
                        + " WHERE root_key = ? AND status = ?",
                toCustodian, ContainerStatus.SEALED.name(), now, rootKey,
                ContainerStatus.TRANSFER_PENDING.name());
    }

    /**
     * 仅更新箱状态（封条核验失败置 SEAL_BROKEN）。
     */
    public void updateStatus(String containerKey, ContainerStatus status, LocalDateTime now) {
        jdbc.update(
                "UPDATE evidence_container SET status = ?, updated_at = ? WHERE container_key = ?",
                status.name(), now, containerKey);
    }

    private static final class ContainerRowMapper implements RowMapper<Container> {
        @Override
        public Container mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new Container(
                    rs.getLong("id"),
                    rs.getString("container_key"),
                    rs.getString("seal_no"),
                    rs.getString("custodian_id"),
                    ContainerStatus.valueOf(rs.getString("status")),
                    rs.getInt("version"),
                    rs.getString("parent_key"),
                    rs.getString("root_key"),
                    rs.getObject("created_at", LocalDateTime.class),
                    rs.getObject("updated_at", LocalDateTime.class));
        }
    }
}

package com.example.starter.evidence;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

/**
 * 箱成员表访问。(member_type, member_key) 全局唯一约束保证任一对象最多一个直接父箱；
 * 成员变更必须先锁定所属根箱行。
 */
@Repository
public class ContainerMemberRepository {

    private static final MemberRowMapper ROW_MAPPER = new MemberRowMapper();

    private final JdbcTemplate jdbc;

    public ContainerMemberRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 追加一条成员关系（装箱）。
     */
    public void insert(String containerKey, String memberType, String memberKey, LocalDateTime now) {
        jdbc.update("""
                        INSERT INTO container_member (container_key, member_type, member_key, created_at)
                        VALUES (?, ?, ?, ?)
                        """,
                containerKey, memberType, memberKey, now);
    }

    /**
     * 移除一条成员关系（拆箱）。
     */
    public void delete(String containerKey, String memberType, String memberKey) {
        jdbc.update(
                "DELETE FROM container_member WHERE container_key = ? AND member_type = ? AND member_key = ?",
                containerKey, memberType, memberKey);
    }

    /**
     * 查询对象当前的成员关系（任一对象最多一条，即唯一直接父箱）。
     */
    public Optional<ContainerMember> findByMember(String memberType, String memberKey) {
        List<ContainerMember> rows = jdbc.query(
                "SELECT * FROM container_member WHERE member_type = ? AND member_key = ?",
                ROW_MAPPER, memberType, memberKey);
        return rows.stream().findFirst();
    }

    /**
     * 按装箱顺序查询箱的直接成员。
     */
    public List<ContainerMember> findByContainerKey(String containerKey) {
        return jdbc.query(
                "SELECT * FROM container_member WHERE container_key = ? ORDER BY id",
                ROW_MAPPER, containerKey);
    }

    /**
     * 查询一组箱的全部直接成员（整树展开用）。
     */
    public List<ContainerMember> findByContainerKeys(List<String> containerKeys) {
        if (containerKeys.isEmpty()) {
            return List.of();
        }
        String placeholders = String.join(", ", containerKeys.stream().map(k -> "?").toList());
        return jdbc.query(
                "SELECT * FROM container_member WHERE container_key IN (" + placeholders + ") ORDER BY id",
                ROW_MAPPER, containerKeys.toArray());
    }

    /**
     * 统计一组箱内的证物成员数量（根箱最多 10 件证物约束）。
     */
    public int countEvidenceMembers(List<String> containerKeys) {
        if (containerKeys.isEmpty()) {
            return 0;
        }
        String placeholders = String.join(", ", containerKeys.stream().map(k -> "?").toList());
        Object[] args = new Object[containerKeys.size() + 1];
        containerKeys.toArray(args);
        args[containerKeys.size()] = ContainerMember.TYPE_EVIDENCE;
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM container_member WHERE container_key IN (" + placeholders + ")"
                        + " AND member_type = ?",
                Integer.class, args);
        return count == null ? 0 : count;
    }

    private static final class MemberRowMapper implements RowMapper<ContainerMember> {
        @Override
        public ContainerMember mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new ContainerMember(
                    rs.getLong("id"),
                    rs.getString("container_key"),
                    rs.getString("member_type"),
                    rs.getString("member_key"),
                    rs.getObject("created_at", LocalDateTime.class));
        }
    }
}

