    String placeholders = String.join(", ", evidenceKeys.stream().map(k -> "?").toList());
    return jdbc.query(
            "SELECT * FROM evidence WHERE evidence_key IN (" + placeholders + ")"
                    + " ORDER BY evidence_key FOR UPDATE",
            ROW_MAPPER, evidenceKeys.toArray());
